public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list cannot be null or empty.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API Name is required.');
            }

            Schema.SObjectType sType = Schema.getGlobalDescribe().get(objectApiName);
            if (sType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDescribe = sType.getDescribe();
            if (!objDescribe.isAccessible()) {
                throw new SearchException('No access to object: ' + objectApiName);
            }

            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
            Set<String> selectFields = new Set<String>{ 'id' };

            for (String f : fields) {
                Schema.SObjectField sField = fieldMap.get(f);
                if (sField == null) {
                    throw new SearchException('Field does not exist: ' + f);
                }
                if (!sField.getDescribe().isAccessible()) {
                    throw new SearchException('No access to field: ' + f);
                }
                selectFields.add(f.toLowerCase());
            }

            Map<String, Object> bindVars = new Map<String, Object>();
            List<String> conditions = new List<String>();
            Integer bindIndex = 0;

            if (filters != null && !filters.isEmpty()) {
                for (String f : filters.keySet()) {
                    Schema.SObjectField sField = fieldMap.get(f);
                    if (sField == null) {
                        throw new SearchException('Filter field does not exist: ' + f);
                    }
                    if (!sField.getDescribe().isAccessible()) {
                        throw new SearchException('No access to filter field: ' + f);
                    }
                    if (!sField.getDescribe().isFilterable()) {
                        throw new SearchException('Field is not filterable: ' + f);
                    }
                    String bindName = 'b' + bindIndex++;
                    conditions.add(f + ' = :' + bindName);
                    bindVars.put(bindName, filters.get(f));
                }
            }

            if (String.isNotBlank(orderByField)) {
                Schema.SObjectField sField = fieldMap.get(orderByField);
                if (sField == null) {
                    throw new SearchException('Order by field does not exist: ' + orderByField);
                }
                if (!sField.getDescribe().isAccessible()) {
                    throw new SearchException('No access to order by field: ' + orderByField);
                }
                if (!sField.getDescribe().isSortable()) {
                    throw new SearchException('Field is not sortable: ' + orderByField);
                }
            }

            String query = 'SELECT ' + String.join(new List<String>(selectFields), ', ') + ' FROM ' + objectApiName;

            if (!conditions.isEmpty()) {
                query += ' WHERE ' + String.join(conditions, ' AND ');
            }

            if (String.isNotBlank(orderByField)) {
                query += ' ORDER BY ' + orderByField + ' ASC';
            }

            query += ' LIMIT ' + maxRows;

            return Database.queryWithBinds(query, bindVars, AccessLevel.USER_MODE);

        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }
}
