public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        Set<String> searchEmails = new Set<String>();

        // Collect cleaned emails to query
        for (Request req : requests) {
            if (String.isNotBlank(req.email)) {
                searchEmails.add(req.email.trim());
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();

        // Query if we have any valid emails to search
        if (!searchEmails.isEmpty()) {
            // SOQL matching is case-insensitive. Order by CreatedDate ASC to get the oldest first.
            List<Contact> contacts = [
                SELECT Id, Email 
                FROM Contact 
                WHERE Email IN :searchEmails 
                ORDER BY CreatedDate ASC
            ];

            for (Contact c : contacts) {
                if (String.isNotBlank(c.Email)) {
                    String normalizedEmail = c.Email.trim().toLowerCase();
                    // Since we ordered by CreatedDate ASC, the first one we see is the earliest.
                    if (!emailToContactId.containsKey(normalizedEmail)) {
                        emailToContactId.put(normalizedEmail, c.Id);
                    }
                }
            }
        }

        // Build the results matching the exact order of the requests
        for (Request req : requests) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;

            if (String.isNotBlank(req.email)) {
                String normalizedSearch = req.email.trim().toLowerCase();
                if (emailToContactId.containsKey(normalizedSearch)) {
                    res.contactId = emailToContactId.get(normalizedSearch);
                    res.found = true;
                }
            }
            results.add(res);
        }

        return results;
    }
}
