public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Map<String, Object> root;
        try {
            Object parsed = JSON.deserializeUntyped(body);
            if (!(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('JSON is not an object');
            }
            root = (Map<String, Object>) parsed;
        } catch (System.JSONException e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        Order order = new Order();

        order.orderNumber = (String) root.get('number');
        if (String.isBlank(order.orderNumber)) {
            throw new PayloadException('Missing or blank number');
        }

        String dateStr = (String) root.get('date');
        if (dateStr != null) {
            order.orderDate = Date.valueOf(dateStr);
        }

        order.currencyCode = (String) root.get('currency');

        Map<String, Object> customer = (Map<String, Object>) root.get('customer');
        if (customer != null) {
            order.customerEmail = (String) customer.get('email');
        }

        order.lines = new List<Line>();
        order.total = 0.00;

        List<Object> linesArray = (List<Object>) root.get('lines');
        if (linesArray != null) {
            for (Object lineObj : linesArray) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    continue;
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;
                Line line = new Line();

                line.sku = (String) lineMap.get('sku');
                if (String.isBlank(line.sku)) {
                    throw new PayloadException('Line missing sku');
                }

                if (lineMap.get('quantity') == null) {
                    throw new PayloadException('Line missing quantity');
                }
                line.quantity = Integer.valueOf(String.valueOf(lineMap.get('quantity')));
                if (line.quantity <= 0) {
                    throw new PayloadException('Line non-positive quantity');
                }

                if (lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Line missing unitPrice');
                }
                line.unitPrice = Decimal.valueOf(String.valueOf(lineMap.get('unitPrice')));
                if (line.unitPrice < 0) {
                    throw new PayloadException('Line negative unitPrice');
                }

                if (lineMap.get('discount') != null) {
                    line.discount = Decimal.valueOf(String.valueOf(lineMap.get('discount')));
                } else {
                    line.discount = 0.0;
                }

                line.lineTotal = (line.quantity * line.unitPrice * (1.0 - line.discount))
                    .setScale(2, System.RoundingMode.HALF_UP);

                order.lines.add(line);
                order.total += line.lineTotal;
            }
        }

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines != null ? order.lines.size() : 0,
            'total' => order.total != null ? order.total : 0.00
        };
        return JSON.serialize(ack);
    }
}
