public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names cannot be blank or null.');
        }

        Schema.SObjectType sObjType;
        try {
            sObjType = Schema.getGlobalDescribe().get(objectApiName);
        } catch (Exception e) {
            throw new PicklistServiceException('Exception retrieving object: ' + e.getMessage());
        }

        if (sObjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult describeResult = sObjType.getDescribe();
        Schema.SObjectField sObjField = describeResult.fields.getMap().get(fieldApiName);

        if (sObjField == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = sObjField.getDescribe();
        if (fieldDescribe.getType() != Schema.DisplayType.PICKLIST && fieldDescribe.getType() != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }

        return options;
    }
}
