public class OpportunityPipelineHandler {
    public static void handleAfter() {
        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isInsert || Trigger.isUndelete) {
            for (Opportunity opp : (List<Opportunity>)Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Opportunity opp : (List<Opportunity>)Trigger.new) {
                Opportunity oldOpp = (Opportunity)Trigger.oldMap.get(opp.Id);
                boolean wasOpen = !oldOpp.IsClosed;
                boolean isOpen = !opp.IsClosed;

                if (opp.AccountId != oldOpp.AccountId || opp.Amount != oldOpp.Amount || opp.IsClosed != oldOpp.IsClosed) {
                    if (wasOpen && oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                    if (isOpen && opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : (List<Opportunity>)Trigger.old) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.put(accId, new Account(
                Id = accId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) sumAmt, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Decimal sumAmt = (Decimal)ar.get('sumAmt');
            Integer cnt = (Integer)ar.get('cnt');

            Account acc = accountsToUpdate.get(accId);
            acc.FB_Open_Pipeline__c = (sumAmt != null) ? sumAmt : 0;
            acc.FB_Open_Opportunities__c = (cnt != null) ? cnt : 0;
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
