    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        delete scope;
        // Empty the recycle bin to immediately free up storage space
        Database.emptyRecycleBin(scope);
    }

    public void finish(Database.BatchableContext bc) {
        // Optional logic after batch completion
    }

    public static Id scheduleNightly() {
        // Schedule to run every day at 02:00 AM
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
