     * it is still highly recommended to use a single aggregate query with GROUP BY. 
     * 
     * Why? 
     * 1. Governor Limits: It consumes only 1 query out of the 100 allowed, leaving more headroom for other triggers/code that might execute in the same transaction.
     * 2. Performance: A single query scans the database once to retrieve the grouped data, whereas four queries force the database to scan the table/indexes four separate times.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        List<String> targetStages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : targetStages) {
            totals.put(stage, 0.00);
        }

        for (AggregateResult ar : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE CloseDate >= :fromDate 
              AND CloseDate <= :toDate
              AND StageName IN :targetStages
            GROUP BY StageName
        ]) {
            String stage = (String) ar.get('StageName');
            Decimal amount = (Decimal) ar.get('totalAmount');
            if (amount != null) {
                totals.put(stage, amount);
            }
        }

        return totals;
    }
}
