public class StaleOpportunityCloser {
    /**
     * Finds all open opportunities with a CloseDate before the cutoff date,
     * sets them to 'Closed Lost', and returns the count of updated records.
     * 
     * NOTE ON THE APPROACH:
     * Processing chunks in a SOQL for loop reduces heap size by only holding 200 
     * records at a time. However, performing DML inside a loop consumes one DML 
     * statement per iteration. Since the synchronous DML statement limit is 150, 
     * this approach will fail if there are more than 30,000 records (150 * 200). 
     * Also, a synchronous transaction might hit the 10-second CPU time limit if 
     * there are heavy triggers on Opportunity. If the volume is expected to grow 
     * beyond a "few thousand", this should be refactored into a Batch Apex class 
     * (Database.Batchable) rather than running synchronously in a Schedulable.
     */
    public static Integer closeStale(Date cutoff) {
        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
            SELECT Id, StageName 
            FROM Opportunity 
            WHERE IsClosed = false AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }
            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
