public class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        // Collect all Account IDs from the cases
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // If there are no accounts to query, we can exit early
        if (accountIds.isEmpty()) {
            return;
        }

        // Query the Accounts once to stay within SOQL limits
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // Set priority for cases linked to 'Hot' accounts
        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
        }
    }
}
