public with sharing class LineItemDiscountHandler {

    /**
     * Applies standard discounts to new Opportunity Line Items if no discount is provided.
     * 
     * NOTE ON CHANGES: 
     * The requirements suggested calling PricingRules.standardDiscountFor(line.Product2Id) 
     * for each line in the loop. However, that method performs a SOQL query inside it. 
     * If we process up to 200 lines (e.g., from the CPQ tool), we would hit the governor 
     * limit of 100 SOQL queries per transaction (System.LimitException: Too many SOQL queries: 101).
     * 
     * To make this bulk-safe, we collect the Product2Ids, perform a single bulk SOQL query 
     * to get the Product Family for all relevant products, and then call the bulk-safe 
     * PricingRules.standardDiscountForFamily(String) method instead.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newList) {
        Set<Id> productIds = new Set<Id>();
        List<OpportunityLineItem> linesToProcess = new List<OpportunityLineItem>();

        // Identify line items that need a discount
        for (OpportunityLineItem line : newList) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
                linesToProcess.add(line);
            }
        }

        if (linesToProcess.isEmpty()) {
            return;
        }

        // Bulk query the products to get their Families
        Map<Id, Product2> productsById = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        // Apply discounts using the bulk-safe helper method
        for (OpportunityLineItem line : linesToProcess) {
            Product2 prod = productsById.get(line.Product2Id);
            if (prod != null) {
                line.Discount = PricingRules.standardDiscountForFamily(prod.Family);
            }
        }
    }
}
