public with sharing class AccountCountrySync {

    public static void syncContacts(List<Account> newAccounts, Map<Id, Account> oldAccountsMap) {
        Map<Id, Account> accountsWithChangedCountry = new Map<Id, Account>();

        // 1. Identify which accounts had their BillingCountry changed
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountsMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                accountsWithChangedCountry.put(acc.Id, acc);
            }
        }

        // If no accounts changed country, we have nothing to do
        if (accountsWithChangedCountry.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // 2. Query ONLY contacts for the accounts that changed. 
        // This avoids hitting the 50,000 SOQL row limit that querying all contacts would cause.
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry 
            FROM Contact 
            WHERE AccountId IN :accountsWithChangedCountry.keySet()
        ]) {
            Account newAcc = accountsWithChangedCountry.get(con.AccountId);
            Account oldAcc = oldAccountsMap.get(con.AccountId);

            // 3. Check if the contact's MailingCountry is blank or matches the old BillingCountry
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldAcc.BillingCountry) {
                con.MailingCountry = newAcc.BillingCountry;
                contactsToUpdate.add(con);
            }
        }

        // 4. Update the matching contacts
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
