import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    hasError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => {
            if (typeof editor.reset === 'function') {
                editor.reset();
            }
        });
    }

    handleSubmit() {
        const editors = Array.from(this.template.querySelectorAll('c-line-item-editor'));

        let allValid = true;
        // We must call validate() on every editor, without short-circuiting
        editors.forEach(editor => {
            if (typeof editor.validate === 'function') {
                const isValid = editor.validate();
                if (!isValid) {
                    allValid = false;
                }
            }
        });

        if (allValid) {
            this.hasError = false;
            const updatedLines = editors.map(editor => editor.getValue());
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: updatedLines }
            }));
        } else {
            this.hasError = true;
        }
    }
}
