import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;

    _inFlight = false;
    _intervalId;

    constructor() {
        super();
        this.handleVisibilityChange = this.handleVisibilityChange.bind(this);
    }

    connectedCallback() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
        if (document.visibilityState === 'visible') {
            this.startPolling(true);
        }
    }

    disconnectedCallback() {
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
        this.stopPolling();
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.startPolling(true);
        } else {
            this.stopPolling();
        }
    }

    startPolling(immediate = false) {
        this.stopPolling();
        if (immediate) {
            this.loadStats();
        }
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, 60000);
    }

    stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        if (this._inFlight || document.visibilityState === 'hidden') {
            return;
        }

        this._inFlight = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.errorMessage = undefined;
        } catch (error) {
            this.errorMessage = error?.body?.message || 'Unknown error';
        } finally {
            this._inFlight = false;
        }
    }

    get hasStats() {
        return this.waiting !== undefined && this.longestWaitMinutes !== undefined;
    }
}
