import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value || [];
        this.initializeActiveValue();
    }

    _value;
    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        if (val) {
            this.activeValue = val;
        } else {
            this.initializeActiveValue();
        }
    }

    @track activeValue;
    activeDescendantId;

    get listboxOptions() {
        return this._options.map((opt) => {
            return {
                ...opt,
                isSelected: this._value === opt.value ? 'true' : 'false'
            };
        });
    }

    connectedCallback() {
        this.initializeActiveValue();
    }

    renderedCallback() {
        this.updateActiveDescendant();
    }

    initializeActiveValue() {
        if (!this._value && this._options && this._options.length > 0) {
            this.activeValue = this._options[0].value;
        } else if (this._value) {
            this.activeValue = this._value;
        }
    }

    updateActiveDescendant() {
        if (this.activeValue) {
            const activeElement = this.template.querySelector(`li[data-value="${this.activeValue}"]`);
            if (activeElement && this.activeDescendantId !== activeElement.id) {
                this.activeDescendantId = activeElement.id;
            }
        }
    }

    handleKeyDown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        const currentIndex = this._options.findIndex(opt => opt.value === this.activeValue);
        let nextIndex = currentIndex !== -1 ? currentIndex : 0;

        switch (key) {
            case 'ArrowDown':
                nextIndex = Math.min(currentIndex + 1, this._options.length - 1);
                break;
            case 'ArrowUp':
                nextIndex = Math.max(currentIndex - 1, 0);
                break;
            case 'Home':
                nextIndex = 0;
                break;
            case 'End':
                nextIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeValue);
                return;
        }

        if (nextIndex !== currentIndex && nextIndex >= 0 && nextIndex < this._options.length) {
            this.activeValue = this._options[nextIndex].value;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        this.activeValue = clickedValue;
        this.selectOption(clickedValue);
    }

    selectOption(val) {
        if (this._value !== val && val !== undefined) {
            this._value = val;
            this.dispatchEvent(new CustomEvent('change', { detail: { value: val } }));
        }
    }
}
