public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Query existing contacts to compare current primary affiliation
        for (Contact con : [
            SELECT Id, npsp__Primary_Affiliation__c 
            FROM Contact 
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            Id newEmployerId = employerByContactId.get(con.Id);

            // Only update if the primary affiliation needs to change
            if (con.npsp__Primary_Affiliation__c != newEmployerId) {
                con.npsp__Primary_Affiliation__c = newEmployerId;
                contactsToUpdate.add(con);
            }
        }

        // Updating the Contact's primary affiliation field leverages NPSP's built-in TDTM triggers.
        // NPSP will automatically create the new Affiliation, mark it as Primary/Current,
        // and update the previous primary affiliation to Former, clearing the Primary checkbox 
        // and setting the End Date to today.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

}
