public class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> diList = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            );
            diList.add(di);
        }

        // Insert the Data Import records to establish an audit trail in the org
        insert diList;

        // Retrieve Data Import settings
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getInstance();
        if (settings == null) {
            settings = new npsp__Data_Import_Settings__c();
        }

        // Process the records synchronously through NPSP's Data Import API
        npsp.BDI_DataImport_API.processDataImportRecords(settings, diList, false);

        // Query the processed records to construct the results
        Map<Id, npsp__DataImport__c> processedDiMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c 
            FROM npsp__DataImport__c 
            WHERE Id IN :diList
        ]);

        // Build the results in the original input order
        for (npsp__DataImport__c originalDi : diList) {
            npsp__DataImport__c processedDi = processedDiMap.get(originalDi.Id);
            ImportResult result = new ImportResult();

            if (processedDi.npsp__Status__c == 'Imported') {
                result.success = true;
                result.contactId = processedDi.npsp__Contact1Imported__c;
                result.opportunityId = processedDi.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = processedDi.npsp__FailureInformation__c;
            }

            results.add(result);
        }

        return results;
    }
}
