public class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty');
        }

        // Isolate the primary contact (first in the list)
        Contact primaryContact = members[0];

        // Inserting the contact without an AccountId triggers NPSP to automatically 
        // create a Household Account, name it correctly, and set this contact as the Primary Contact.
        insert primaryContact;

        // Retrieve the newly created Household Account Id
        Id householdAccountId = [SELECT AccountId FROM Contact WHERE Id = :primaryContact.Id].AccountId;

        // If there are more members, associate them with the newly created Household Account
        if (members.size() > 1) {
            List<Contact> otherMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdAccountId;
                otherMembers.add(c);
            }
            // Inserting the remaining members will add them to the household 
            // and trigger NPSP to update the household name and greetings automatically.
            insert otherMembers;
        }

        return householdAccountId;
    }
}
