public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id cannot be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date cannot be null.');
        }

        List<Contact> contacts = [SELECT Id, FirstName, LastName, AccountId FROM Contact WHERE Id = :contactId];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact donor = contacts[0];

        String y = String.valueOf(giftDate.year());
        String m = String.valueOf(giftDate.month()).leftPad(2, '0');
        String d = String.valueOf(giftDate.day()).leftPad(2, '0');
        String dateStr = y + '-' + m + '-' + d;

        String oppName = '';
        if (String.isNotBlank(donor.FirstName)) {
            oppName += donor.FirstName + ' ';
        }
        oppName += donor.LastName + ' Donation ' + dateStr;

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won'
        );
        insert opp;

        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c 
            WHERE npe01__Opportunity__c = :opp.Id
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c paymentToKeep = payments[0];
            paymentToKeep.npe01__Payment_Amount__c = amount;
            paymentToKeep.npe01__Payment_Date__c = giftDate;
            paymentToKeep.npe01__Scheduled_Date__c = giftDate;
            paymentToKeep.npe01__Paid__c = true;
            update paymentToKeep;

            if (payments.size() > 1) {
                List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    toDelete.add(payments[i]);
                }
                delete toDelete;
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId = :opp.Id
        ];

        Set<Id> contactsWithRoles = new Set<Id>();
        for (OpportunityContactRole ocr : existingRoles) {
            contactsWithRoles.add(ocr.ContactId);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();

        if (!contactsWithRoles.contains(donor.Id)) {
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = donor.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
            contactsWithRoles.add(donor.Id);
        }

        if (donor.AccountId != null) {
            List<Contact> householdMembers = [
                SELECT Id 
                FROM Contact 
                WHERE AccountId = :donor.AccountId 
                  AND Id != :donor.Id
            ];

            for (Contact member : householdMembers) {
                if (!contactsWithRoles.contains(member.Id)) {
                    rolesToInsert.add(new OpportunityContactRole(
                        OpportunityId = opp.Id,
                        ContactId = member.Id,
                        Role = 'Household Member',
                        IsPrimary = false
                    ));
                    contactsWithRoles.add(member.Id);
                }
            }
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        return opp.Id;
    }
}
