public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist, 
        List<SObject> oldlist, 
        npsp.TDTM_Runnable.Action triggerAction, 
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // We only process AfterInsert and AfterUpdate
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert && 
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        Map<Id, Opportunity> oldOppsMap = new Map<Id, Opportunity>();

        if (oldlist != null) {
            oldOppsMap = new Map<Id, Opportunity>((List<Opportunity>) oldlist);
        }

        for (Opportunity opp : newOpps) {
            Boolean isNowClosedWon = (opp.IsWon == true || opp.StageName == 'Closed Won');
            Boolean isNowAmountMet = (opp.Amount != null && opp.Amount >= 5000);
            Boolean isQualifyingNow = isNowClosedWon && isNowAmountMet;

            Boolean wasQualifyingBefore = false;

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldOppsMap.get(opp.Id);
                if (oldOpp != null) {
                    Boolean wasClosedWon = (oldOpp.IsWon == true || oldOpp.StageName == 'Closed Won');
                    Boolean wasAmountMet = (oldOpp.Amount != null && oldOpp.Amount >= 5000);
                    wasQualifyingBefore = wasClosedWon && wasAmountMet;
                }
            }

            if (isQualifyingNow && !wasQualifyingBefore) {
                Task followUpTask = new Task(
                    Subject = 'Major gift thank-you call',
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opp.Id,
                    WhoId = opp.npsp__Primary_Contact__c,
                    OwnerId = opp.OwnerId,
                    ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null
                );

                dmlWrapper.objectsToInsert.add(followUpTask);
            }
        }

        return dmlWrapper;
    }
}
