public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableIds;
        }

        List<Id> idList = new List<Id>(recordIds);
        Id currentUserId = UserInfo.getUserId();

        // UserRecordAccess only supports querying up to 200 records at a time
        Integer chunkSize = 200;

        for (Integer i = 0; i < idList.size(); i += chunkSize) {
            Set<Id> chunk = new Set<Id>();
            Integer endIdx = Math.min(i + chunkSize, idList.size());

            for (Integer j = i; j < endIdx; j++) {
                chunk.add(idList[j]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId 
                FROM UserRecordAccess 
                WHERE UserId = :currentUserId 
                  AND RecordId IN :chunk 
                  AND HasEditAccess = true
            ]) {
                editableIds.add(access.RecordId);
            }
        }

        return editableIds;
    }
}
