public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        processContacts((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processContacts((List<Contact>) triggerNew, new Map<Id, Contact>((List<Contact>) triggerOld));
    }

    private void processContacts(List<Contact> triggerNew, Map<Id, Contact> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        List<Contact> contactsToCheck = new List<Contact>();

        for (Contact c : triggerNew) {
            if (c.AccountId != null && c.Email != null) {
                if (oldMap == null || c.AccountId != oldMap.get(c.Id).AccountId || c.Email != oldMap.get(c.Id).Email) {
                    accountIds.add(c.AccountId);
                    emails.add(c.Email);
                    contactsToCheck.add(c);
                }
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email 
            FROM Contact 
            WHERE AccountId IN :accountIds 
              AND Email IN :emails
        ];

        Map<String, Set<Id>> existingMap = new Map<String, Set<Id>>();
        for (Contact c : existingContacts) {
            if (c.Email != null) {
                String key = String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();
                if (!existingMap.containsKey(key)) {
                    existingMap.put(key, new Set<Id>());
                }
                existingMap.get(key).add(c.Id);
            }
        }

        Set<String> seenInBatch = new Set<String>();
        for (Contact c : contactsToCheck) {
            String key = String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();

            Boolean isDuplicate = false;

            if (existingMap.containsKey(key)) {
                for (Id existingId : existingMap.get(key)) {
                    if (c.Id == null || c.Id != existingId) {
                        isDuplicate = true;
                        break;
                    }
                }
            }

            if (!isDuplicate && seenInBatch.contains(key)) {
                isDuplicate = true;
            }

            if (isDuplicate) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                seenInBatch.add(key);
            }
        }
    }
}
