public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(getAffectedAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        recalculate(getAffectedAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(getAffectedAccountIds(null, triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(getAffectedAccountIds(triggerNew, null));
    }

    private Set<Id> getAffectedAccountIds(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();

        if (triggerNew != null && triggerOld == null) {
            for (Case c : (List<Case>)triggerNew) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        } else if (triggerNew == null && triggerOld != null) {
            for (Case c : (List<Case>)triggerOld) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        } else if (triggerNew != null && triggerOld != null) {
            for (Integer i = 0; i < triggerNew.size(); i++) {
                Case newCase = (Case)triggerNew[i];
                Case oldCase = (Case)triggerOld[i];
                if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                    if (newCase.AccountId != null) {
                        accountIds.add(newCase.AccountId);
                    }
                    if (oldCase.AccountId != null) {
                        accountIds.add(oldCase.AccountId);
                    }
                }
            }
        }

        return accountIds;
    }

    private void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        // Initialize all affected accounts to 0 open cases
        for (Id accId : accountIds) {
            accountsToUpdate.put(accId, new Account(Id = accId, FB_Open_Case_Count__c = 0));
        }

        // Count actual open cases using AggregateResult
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) openCount 
            FROM Case 
            WHERE AccountId IN :accountIds 
            AND IsClosed = false 
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Integer count = (Integer)ar.get('openCount');
            accountsToUpdate.get(accId).FB_Open_Case_Count__c = count;
        }

        update accountsToUpdate.values();
    }
}
